def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    my_last, opp_last = history[-1]
    if n == 1:
        return 'C'
    if n == 2:
        return 'C' if opp_last == 'C' else 'D'
    opp_defections = sum(1 for m, o in history if o == 'D')
    opp_coops = n - opp_defections
    if n >= 4 and opp_defections == n:
        return 'D'
    if n >= 4 and opp_coops == n:
        if n >= 96:
            return 'D'
        return 'C'
    if n >= 2 and opp_last == 'D' and history[-2][1] == 'D':
        if n >= 3 and history[-3][1] == 'D':
            if n >= 4 and history[-4][1] == 'D':
                return 'D' if rng.random() < 0.9 else 'C'
            return 'D' if rng.random() < 0.85 else 'C'
        return 'D' if rng.random() < 0.8 else 'C'
    if n >= 90:
        rate = opp_coops / n
        if rate > 0.7:
            return 'D'
        if rate < 0.3:
            return 'D'
        return 'D' if opp_last == 'C' else 'C'
    if n >= 80:
        rate = opp_coops / n
        if rate > 0.8:
            return 'C' if opp_last == 'C' else 'D'
        if rate < 0.25:
            return 'D'
        return 'C' if opp_last == 'C' else 'D'
    recent = history[-8:]
    recent_opp_d = sum(1 for m, o in recent if o == 'D')
    recent_my_d = sum(1 for m, o in recent if m == 'D')
    if recent_opp_d == 0:
        if n > 25 and recent_my_d == 0 and opp_coops / n > 0.9:
            if rng.random() < 0.08:
                return 'D'
        return 'C'
    if recent_opp_d >= 5:
        return 'D' if rng.random() < 0.9 else 'C'
    if recent_opp_d >= 3:
        if recent_my_d >= 3:
            return 'C'
        return 'D'
    if recent_opp_d == 2:
        if opp_last == 'D':
            return 'D' if rng.random() < 0.75 else 'C'
        return 'C'
    if recent_opp_d == 1:
        if opp_last == 'D' and my_last == 'C':
            return 'D'
        if opp_last == 'D' and my_last == 'D':
            return 'C' if rng.random() < 0.4 else 'D'
        return 'C'
    return 'C'
